    """Get stored messages from database."""
    try:
        limit = int(request.query.get("limit", 50))
        offset = int(request.query.get("offset", 0))
        channel = request.query.get("channel")

        # Validate limits
        limit = min(max(limit, 1), 1000)
        offset = max(offset, 0)

        messages = self.db.get_messages(channel=channel, limit=limit, offset=offset)
        total_count = self.db.get_message_count(channel=channel)

        return web.json_response({
            "messages": messages,
            "limit": limit,
            "offset": offset,
            "total": total_count,
            "count": len(messages),
            "timestamp": datetime.now(timezone.utc).isoformat(),
        })
    except (ValueError, TypeError):
        return web.json_response({
            "error": "Invalid query parameters",
            "timestamp": datetime.now(timezone.utc).isoformat(),
        }, status=400)

async def _history_handler(self, request: web.Request) -> web.Response:
    """Get message history for a specific channel since a timestamp."""
    try:
        channel = request.query.get("channel")
        since = request.query.get("since")
        limit = int(request.query.get("limit", 50))

        if not channel:
            return web.json_response({
                "error": "channel parameter is required",
                "timestamp": datetime.now(timezone.utc).isoformat(),
            }, status=400)

        if not since:
            return web.json_response({
                "error": "since parameter is required (ISO 8601 timestamp)",
                "timestamp": datetime.now(timezone.utc).isoformat(),
            }, status=400)

        # Validate limit
        limit = min(max(limit, 1), 1000)

        messages = self.db.get_messages_since(channel, since, limit)
        has_more = len(messages) >= limit

        return web.json_response({
            "channel": channel,
            "messages": messages,
            "limit": limit,
            "count": len(messages),
            "has_more": has_more,
            "timestamp": datetime.now(timezone.utc).isoformat(),
        })
    except (ValueError, TypeError) as e:
        return web.json_response({
            "error": "Invalid query parameters",
            "timestamp": datetime.now(timezone.utc).isoformat(),
        }, status=400)

